\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{booktabs}
\usepackage{array}
\pagestyle{empty}

% ── Custom Ocean-to-Warm Color Theme ──
\definecolor{primary}{HTML}{0B3D5C}     % deep ocean blue
\definecolor{secondary}{HTML}{1A5276}   % medium ocean blue
\definecolor{accent}{HTML}{C0392B}      % warm red (warming)
\definecolor{bgposter}{HTML}{E8F1F8}    % cool light blue tint
\definecolor{redbg}{HTML}{FDF2F2}       % warm pink tint for redcard
\definecolor{bluebg}{HTML}{E8F4FD}      % cool blue tint for bluecard
\definecolor{darkbg}{HTML}{F0F5FA}      % neutral blue tint for darkcard
\definecolor{redtitlebg}{HTML}{FADBD8}
\definecolor{bluetitlebg}{HTML}{D6EAF8}
\definecolor{darktitlebg}{HTML}{D4E6F1}
\definecolor{textdark}{HTML}{1F2937}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FCE8E8}
\definecolor{warmamber}{HTML}{E67E22}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[4mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=accent!15!white,
    borderline west={8pt}{0pt}{accent},
    left=18pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accent,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{84}{100}\selectfont\bfseries 300 Years of Sclerosponge Thermometry Shows\\[8pt]Global Warming Has Exceeded 1.5\,°C}\\[18pt]
  {\fontsize{38}{46}\selectfont Nature Climate Change \,|\, 2024 \,|\, Sclerosponge Sr/Ca Proxy Reconstruction}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{white!75} AGU / Nature Climate Change Symposium \,|\, Poster Session}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center, borderline south={4pt}{0pt}{primary!40},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{84}\selectfont\bfseries\color{accent} >1.5\,°C}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textdark} Total Warming (True Pre-Industrial)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{84}\selectfont\bfseries\color{accent} ~0.5\,°C}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textdark} Hidden Pre-Industrial Warming}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{84}\selectfont\bfseries\color{warmamber} ~1.2\,°C}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textdark} IPCC Reported (1850–1900)}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ ROW A: COLUMN 1 — WHY SCLEROSPONGES? ══
\posterbox[bluecard, title={Why Sclerosponges?}
]{name=background, column=1, between=row6 and row11}{
  \fontsize{32}{42}\selectfont
  Long-lived marine organisms whose aragonite skeletons preserve Sr/Ca ratios that faithfully track ambient water temperature.
  \vspace{8pt}
  \begin{itemize}
    \item \textbf{Continuous growth} over centuries — unbroken annual records
    \item \textbf{Tropical sensitivity} — Caribbean sites capture global SST variability
    \item \textbf{Independent} of instrumental networks (begin ~1850)
  \end{itemize}
  \vspace{10pt}
  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{30}{38}\selectfont\bfseries\color{secondary} Key advantage:}\\[4pt]
    {\fontsize{28}{36}\selectfont Extends temperature record back to \textbf{~1700 CE}}\vspace{6pt}%
  }}
}

% ══ ROW A: COLUMN 2 — METHOD PIPELINE ══
\posterbox[darkcard, title={Data \& Methods}
]{name=methods, column=2, between=row6 and row11}{
  \fontsize{30}{40}\selectfont
  \posterfig{0.96}{figures/method_pipeline.png}{Sclerosponge Sr/Ca thermometry pipeline from specimen collection to 300-year reconstruction.}
  \vspace{6pt}
  \begin{itemize}
    \item Specimens from Caribbean reefs at \textbf{33–91\,m} depth
    \item Sr/Ca measured via \textbf{ICP-OES}, calibrated against SST 1960+ ($r^2 > 0.9$)
    \item Validated against \textbf{HadCRUT5} and NOAA ERSSTv5
  \end{itemize}
}

% ══ ROW A: COLUMN 3 — KEY FINDING / BASELINE COMPARISON ══
\posterbox[redcard, title={Pre-Industrial Baseline Matters}
]{name=baseline, column=3, between=row6 and row11}{
  \fontsize{30}{40}\selectfont
  The IPCC's 1850–1900 ``pre-industrial'' reference already contained significant anthropogenic warming.
  \vspace{10pt}
  \posterfig{0.96}{figures/hidden_warming.png}{Side-by-side comparison: IPCC-reported warming vs. true pre-industrial total.}
  \vspace{6pt}
  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{30}{38}\selectfont\bfseries\color{accent} The gap: ~0.5\,°C}}\vspace{6pt}%
  }}
}

% ══ ROW B: COLUMN 1 — TIMELINE MILESTONES ══
\posterbox[bluecard, title={300-Year Timeline — Key Milestones}
]{name=timeline, column=1, between=row11 and row16}{
  \fontsize{28}{38}\selectfont
  \renewcommand{\arraystretch}{1.8}
  \begin{tabular}{>{\bfseries\color{secondary}}l p{0.60\linewidth}}
    \toprule
    \rowcolor{secondary!15}
    1700–1790 & Stable pre-industrial baseline \\
    \rowcolor{white}
    1790–1850 & Early industrial warming onset \\
    \rowcolor{secondary!15}
    1850–1900 & Already ~0.5\,°C above true baseline \\
    \rowcolor{white}
    1900–1960 & Gradual warming; volcanic cooling visible \\
    \rowcolor{secondary!15}
    1960–2000 & Accelerating trend; proxies converge with instruments \\
    \rowcolor{white}
    2000–present & \textbf{>1.5\,°C exceeded} relative to true baseline \\
    \bottomrule
  \end{tabular}
  \vspace{10pt}
  \colorbox{warmamber!18}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{28}{36}\selectfont\color{warmamber} By ~2020, the true pre-industrial 1.5\,°C threshold was crossed.}\vspace{6pt}%
  }}
}

% ══ ROW B: COLUMN 2 — HERO FIGURE: TEMPERATURE RECONSTRUCTION ══
\posterbox[darkcard, title={300-Year Temperature Reconstruction}
]{name=herofig, column=2, span=2, between=row11 and row16}{
  \posterfig{0.98}{figures/temperature_timeline.png}{Reconstructed global temperature anomaly from sclerosponge Sr/Ca proxies (~1700–2024), showing the divergence from instrumental records before ~1850 and the crossing of the 1.5\,°C Paris threshold by ~2020.}
}

% ══ ROW C: COLUMN 1 — POLICY IMPLICATIONS ══
\posterbox[redcard, title={Policy \& Climate Target Implications}
]{name=implications, column=1, between=row16 and bottom}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}
    \item Paris 1.5\,°C target uses 1850–1900 — \textbf{not truly pre-industrial}
    \item Sclerosponge baseline \textbf{reduces remaining carbon budget} for 1.5\,°C to ~zero
    \item 2.0\,°C guardrail is closer: only ~\textbf{0.3\,°C} headroom left (not ~0.8\,°C)
    \item Urgency of \textbf{rapid emissions reductions} underscored
  \end{itemize}
  \vspace{8pt}
  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{28}{36}\selectfont\bfseries\color{accent} Transparent baselines are essential for credible climate policy.}\vspace{6pt}%
  }}
}

% ══ ROW C: COLUMN 2 — KEY TAKEAWAYS ══
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=2, between=row16 and bottom}{
  \fontsize{32}{42}\selectfont
  \begin{enumerate}
    \item Sclerosponge proxies reveal \textbf{~0.5\,°C of hidden warming} before 1850
    \item True pre-industrial total warming is \textbf{>1.5\,°C} as of early 2020s
    \item Baseline choice fundamentally changes perceived carbon budgets and policy urgency
  \end{enumerate}
}

% ══ ROW C: COLUMN 3 — REFERENCES & QR ══
\posterbox[darkcard, title={References}
]{name=references, column=3, between=row16 and bottom}{
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item McCulloch et al.~(2024). ``300-year sclerosponge record shows global warming has exceeded 1.5\,°C.'' \textit{Nature Climate Change}.
    \item IPCC AR6 WGI (2021). \textit{Climate Change 2021: The Physical Science Basis}. Cambridge Univ. Press.
    \item Morice et al.~(2021). HadCRUT5 analysis. \textit{J. Geophys. Res. Atmos.}
    \item Huang et al.~(2020). NOAA ERSSTv5. \textit{J. Climate}.
  \end{itemize}
  \vspace{10pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{28}{36}\selectfont\bfseries\color{primary} Data \& Code:}\\[4pt]
    {\fontsize{26}{34}\selectfont\color{textdark} github.com/sclerosponge-climate/reconstruction}\vspace{6pt}%
  }}
}

\end{tcbposter}
\end{document}

